INSERT INTO quiz_questions VALUES (1, 1, '03', '경제 순환', '경기 확장 국면에 대한 설명으로 가장 적절한 것은?', '소비와 생산이 줄고 기업이 투자를 멈추는 시기', '기업 활동과 소비가 활발해져 매출·고용·투자가 증가할 수 있는 시기', '주가가 반드시 오르는 시기', '모든 산업의 이익이 같은 비율로 늘어나는 시기', 1, '확장은 소비·생산·고용·투자가 활발해질 수 있는 국면입니다. 그렇다고 모든 기업이나 주가가 반드시 같은 방향으로 움직이는 것은 아닙니다.');
INSERT INTO quiz_questions VALUES (1, 2, '03', '산업 분석', '산업을 분석할 때 개별 회사 외에 함께 확인할 사항으로 가장 적절한 것은?', '대표이사의 취미만 확인한다', '신규 진입, 대체재, 고객·공급자의 교섭력과 경쟁 강도', '하루 주가 등락만 확인한다', '인터넷 댓글 수만 확인한다', 1, '산업 구조는 신규 진입자, 대체재, 고객·공급자의 힘, 기존 경쟁 등으로 살펴볼 수 있습니다.');
INSERT INTO quiz_questions VALUES (1, 3, '03', '공시', '국내 상장회사의 사업보고서와 주요 계약 등 공식 정보를 우선 확인할 곳은?', 'DART 전자공시시스템', '주식 단체 대화방', '출처 없는 문자메시지', '검색어 자동완성', 0, 'DART는 기업이 제출한 사업보고서와 주요 공시 원문을 확인하는 전자공시시스템입니다.');
INSERT INTO quiz_questions VALUES (1, 4, '03', '한국 경제', '한국 경제를 읽을 때 세계 수요·환율·원자재 가격을 함께 보는 이유로 가장 적절한 것은?', '한국은 해외와 전혀 거래하지 않기 때문', '제조업과 수출 비중이 높아 세계 경제와 공급망의 영향을 받기 때문', '국내 주식은 환율과 무관하기 때문', '수출은 기업 실적과 관계없기 때문', 1, '한국은 수출과 제조업의 비중이 큰 개방형 경제이므로 해외 수요, 환율, 원자재 가격이 기업 실적과 시장에 영향을 줄 수 있습니다.');
INSERT INTO quiz_questions VALUES (2, 1, '04', '재무제표', '재무상태표의 기본 관계로 옳은 것은?', '자산 = 부채 + 자본', '매출 = 자산 + 부채', '현금 = 이익 + 주가', '자본 = 매출 - 세금', 0, '재무상태표에서는 회사가 가진 자산이 부채와 자본의 합으로 구성됩니다.');
INSERT INTO quiz_questions VALUES (2, 2, '04', '이익과 현금', '매출과 이익이 늘었는데도 현금이 부족할 수 있는 사례로 가장 적절한 것은?', '외상 판매 대금을 아직 받지 못한 경우', '회사가 현금을 받은 경우', '부채가 전혀 없는 경우', '주가가 오른 경우', 0, '장부상 매출·이익이 있어도 판매 대금을 아직 받지 못하면 실제 현금은 부족할 수 있습니다.');
INSERT INTO quiz_questions VALUES (2, 3, '04', '기업가치', 'PER과 PBR을 사용할 때 가장 바람직한 태도는?', '숫자 하나만으로 매수 여부를 결정한다', '서로 다른 업종의 회사를 무조건 같은 기준으로 비교한다', '사업 모델·성장 단계·부채가 비슷한 회사와 함께 비교한다', '적자 회사에도 PER만 사용한다', 2, 'PER·PBR은 하나의 참고 지표입니다. 사업 구조와 성장 단계가 비슷한 기업을 비교하고 현금·부채·위험도 함께 봐야 합니다.');
INSERT INTO quiz_questions VALUES (2, 4, '04', '공시 읽기', '유상증자 공시를 볼 때 확인할 내용으로 가장 적절한 것은?', '새 자금의 사용처와 기존 주주의 지분 영향', '댓글의 긍정·부정 비율만 확인', '공시 제목만 읽고 바로 주문', '주가 색깔만 확인', 0, '유상증자는 새 자금을 모으는 방식입니다. 자금 사용처와 기존 주주의 지분 희석 가능성을 함께 확인해야 합니다.');
INSERT INTO quiz_questions VALUES (3, 1, '05', '티커', '미국 주식을 주문하기 전에 티커와 함께 확인해야 할 사항으로 가장 적절한 것은?', '종목명·거래 시장·보통주 또는 ETF 여부', '종목 이름의 길이만 확인', '전날 댓글 수만 확인', '색상 설정만 확인', 0, '미국 시장에는 비슷한 이름의 기업, 서로 다른 주식 종류, ETF가 있을 수 있으므로 종목명·티커·시장·상품 종류를 함께 확인해야 합니다.');
INSERT INTO quiz_questions VALUES (3, 2, '05', '거래량', '가격 상승과 거래량 급증을 해석하는 태도로 가장 적절한 것은?', '다음 날 상승이 확정되었다', '많은 참여가 있었을 수 있으나 공시·뉴스·평소 거래량을 함께 확인한다', '거래량은 항상 나쁜 신호다', '회사의 실적은 볼 필요가 없다', 1, '거래량 증가는 관심이나 주문 집중의 단서일 뿐입니다. 원인과 지속 가능성은 공시·실적·뉴스로 따로 확인해야 합니다.');
INSERT INTO quiz_questions VALUES (3, 3, '05', '캔들', '양봉의 의미로 가장 적절한 것은?', '종가가 시가보다 높은 캔들', '종가가 시가보다 낮은 캔들', '거래량이 없는 날', '다음 날 상승을 보장하는 신호', 0, '양봉은 해당 기간의 종가가 시가보다 높았다는 기록입니다. 미래 가격을 보장하지는 않습니다.');
INSERT INTO quiz_questions VALUES (3, 4, '05', '찌라시', '확인되지 않은 찌라시를 받았을 때 가장 적절한 행동은?', '놓칠까 봐 즉시 시장가로 매수한다', '가격이 올랐으니 사실로 믿는다', 'DART·KIND 등 공식 원문을 확인하고 주문을 멈춘다', '여러 대화방에 먼저 전달한다', 2, '근거 없는 소문은 가격과 거래량을 흔들 수 있습니다. 공식 공시와 원문을 확인하기 전에는 주문과 재전파를 피하는 것이 안전합니다.');
INSERT INTO quiz_questions VALUES (4, 1, '06', '주식 종류', '보통주와 우선주의 일반적인 차이에 대한 설명으로 가장 적절한 것은?', '우선주는 항상 의결권이 더 많다', '보통주는 의결권을 가질 수 있고 우선주는 배당 조건이 다르며 의결권이 없는 경우가 많다', '두 주식은 항상 가격과 권리가 같다', '우선주는 원금이 보장된다', 1, '보통주는 주주총회 의결권과 연결될 수 있고, 우선주는 배당 조건이 다르거나 의결권이 없는 경우가 많습니다. 세부 조건은 회사별로 확인해야 합니다.');
INSERT INTO quiz_questions VALUES (4, 2, '06', 'ETF', 'ETF에 대한 설명으로 가장 적절한 것은?', '예금처럼 원금이 보장된다', '여러 자산을 담을 수 있고 거래소에서 주식처럼 거래되는 펀드다', '한 회사 주식만 살 수 있다', '수수료와 위험을 확인할 필요가 없다', 1, 'ETF는 여러 자산을 담을 수 있는 펀드이면서 거래소에서 주식처럼 거래됩니다. 가격 하락 가능성과 보수·구성 자산을 확인해야 합니다.');
INSERT INTO quiz_questions VALUES (4, 3, '06', '주문', '지정가 주문의 설명으로 가장 적절한 것은?', '어떤 가격이든 즉시 체결되는 주문', '내가 정한 가격 또는 그보다 유리한 가격에서만 체결을 기다리는 주문', '원금 손실을 없애는 주문', '수량을 입력하지 않는 주문', 1, '지정가 주문은 투자자가 정한 가격 조건에서 체결됩니다. 상대 주문이 없으면 미체결로 남을 수 있습니다.');
INSERT INTO quiz_questions VALUES (4, 4, '06', '거래 유의사항', '처음 주식 계좌를 사용할 때 가장 안전한 방법은?', '신용·미수 기능부터 켠다', '공식 증권사 앱을 확인하고 소액·현금 거래로 화면과 주문을 익힌다', '문자로 받은 설치 파일을 바로 실행한다', '생활비를 모두 입금한다', 1, '처음에는 공식 앱인지 확인하고, 필요한 돈과 분리한 소액으로 현금 거래 절차를 익히는 편이 안전합니다.');
INSERT INTO quiz_questions VALUES (5, 1, '07', '분산투자', '분산투자의 목적로 가장 적절한 것은?', '손실을 완전히 없애는 것', '특정 기업·산업·국가에 위험이 집중되는 것을 줄이는 것', '단기간 수익을 보장하는 것', '모든 자산을 같은 방향으로 움직이게 하는 것', 1, '분산투자는 한 곳의 손실이 전체 자산에 미치는 영향을 낮추려는 방법입니다. 손실 자체를 없애지는 못합니다.');
INSERT INTO quiz_questions VALUES (5, 2, '07', '리밸런싱', '리밸런싱의 설명으로 가장 적절한 것은?', '매일 모든 자산을 사고파는 것', '가격을 정확히 맞히는 기술', '정한 자산 비중에서 크게 벗어났을 때 원래 계획에 가깝게 조정하는 것', '수익이 난 자산만 계속 사는 것', 2, '리밸런싱은 미래 가격을 맞히기보다, 처음 정한 위험 수준과 자산배분 계획을 지키기 위한 점검 방법입니다.');
INSERT INTO quiz_questions VALUES (5, 3, '07', '손실 관리', '투자금이 50% 줄었을 때 원래 금액으로 돌아가기 위해 필요한 수익률은?', '50%', '75%', '100%', '150%', 2, '100만 원이 50만 원이 되면 50만 원을 다시 100만 원으로 만들려면 100% 상승이 필요합니다. 큰 손실 관리가 중요한 이유입니다.');
INSERT INTO quiz_questions VALUES (5, 4, '07', '투자 심리', '확증 편향을 줄이는 습관으로 가장 적절한 것은?', '내 의견과 같은 정보만 찾는다', '매수·매도 이유를 기록하고 반대되는 자료도 확인한다', '가격이 오르면 이유 없이 비중을 늘린다', '손실을 무시하고 기록하지 않는다', 1, '확증 편향은 자신이 믿는 정보만 찾는 경향입니다. 결정 이유를 기록하고 반대 근거도 확인하면 감정적 판단을 줄이는 데 도움이 됩니다.');
INSERT INTO quiz_questions VALUES (3, 5, '05', '캔들 구조', '캔들에서 ‘위꼬리(Upper Shadow)’가 의미하는 것으로 가장 적절한 것은?', '장중에 더 낮게 내려갔지만 종가까지 올라온 구간', '장중에 더 높이 올랐지만 종가까지 내려온 구간', '시가와 종가가 같다는 뜻', '거래가 전혀 없었다는 뜻', 1, '위꼬리는 몸통 위로 나온 가는 선으로, 장중 고가까지 올랐다가 종가까지 내려온 흔적을 보여줍니다.');
INSERT INTO quiz_questions VALUES (3, 6, '05', '도지', '포프라이스 도지(4-Price Doji)에 대한 설명으로 가장 적절한 것은?', '위아래 꼬리가 모두 매우 긴 모양', '아래꼬리만 길고 위꼬리가 거의 없는 T자 모양', '꼬리 없이 시가·고가·저가·종가가 거의 같은 일자 모양', '반드시 다음 날 급등을 예고하는 신호', 2, '포프라이스 도지는 거래가 극히 적거나 동시호가처럼 한 가격에서만 거래될 때 나타나는 특수한 모습입니다.');
INSERT INTO quiz_questions VALUES (3, 7, '05', '차트 패턴', '헤드 앤 숄더 패턴에서 하락 전환을 확인하는 핵심 조건으로 가장 적절한 것은?', '세 번째 고점이 첫 번째 고점보다 훨씬 높아지는 것', '두 저점을 이은 목선을 거래량과 함께 아래로 이탈하는 것', '거래량이 완전히 사라지는 것', '이동평균선이 사라지는 것', 1, '헤드 앤 숄더는 목선(두 저점을 이은 선) 이탈 여부가 확인의 핵심이며, 이탈 없이 다시 오르는 경우도 많아 단정할 수 없습니다.');
INSERT INTO quiz_questions VALUES (3, 8, '05', '변동성 지표', 'VIX(변동성지수)에 대한 설명으로 가장 적절한 것은?', '주가가 반드시 내린다는 예측 지표', 'S&P 500 옵션 가격으로 계산한 향후 30일 기대 변동성', '한국 시장에서만 쓰이는 지표', '항상 0~10 사이의 값을 가짐', 1, 'VIX는 미국 S&P 500 옵션 가격으로 계산한 내재변동성 지표이며, 시장이 얼마나 흔들릴 것으로 예상되는지를 보여줄 뿐 방향을 예측하지는 않습니다.');
INSERT INTO quiz_questions VALUES (3, 9, '05', '모멘텀', '모멘텀 투자에 대한 설명으로 가장 적절한 것은?', '가격이 낮은 종목을 찾아 매수하는 가치투자와 같은 개념이다', '최근 수익률이 높았던 종목을 사고 낮았던 종목은 피하는 전략이다', '반드시 시장 평균보다 높은 수익을 보장한다', '거래량과는 관계가 없다', 1, '모멘텀 투자는 ‘이미 오르고 있는 흐름에 올라탄다’는 생각에 가까우며, 이미 많이 오른 만큼 되돌림 위험도 함께 커질 수 있습니다.');
INSERT INTO quiz_questions VALUES (4, 5, '06', '호가창', '호가 차이(스프레드)에 대한 설명으로 가장 적절한 것은?', '가장 높은 매수호가와 가장 낮은 매도호가의 차이', '하루 동안의 총 거래량', '종가와 시가의 차이', '상한가와 하한가의 평균', 0, '스프레드는 매도1호가와 매수1호가의 차이이며, 거래량이 적은 종목일수록 이 차이가 넓어 시장가 주문 시 예상보다 불리한 가격에 체결될 수 있습니다.');
INSERT INTO quiz_questions VALUES (4, 6, '06', '분할매수', '분할매수에서 평단(평균 매수 단가)을 구하는 방법으로 옳은 것은?', '각 회차 매수 가격의 단순 평균', '총 매수금액 ÷ 총 보유 수량', '가장 최근 매수 가격', '가장 낮았던 매수 가격', 1, '평단은 총 매수금액을 총 보유 수량으로 나눈 값이며, 특정 회차의 가격이 아니라 수량으로 가중 평균한 값입니다.');
INSERT INTO quiz_questions VALUES (4, 7, '06', '배당', '배당락일에 대한 설명으로 가장 적절한 것은?', '배당금이 실제로 계좌에 입금되는 날', '새로 산 주식에 배당 권리가 붙지 않는 첫 거래일', '배당을 결정하는 주주총회가 열리는 날', '반드시 주가가 오르는 날', 1, '배당락일 이후에 주식을 사면 그 배당을 받을 권리가 없습니다. 배당 권리가 분리되며 주가가 조정될 수 있지만 반드시 정해진 방향으로 움직이는 것은 아닙니다.');
INSERT INTO quiz_questions VALUES (4, 8, '06', 'CAPM', 'CAPM에서 ‘시장 위험 프리미엄’을 구하는 식으로 옳은 것은?', '무위험 이자율 × 베타', '시장 기대수익률 − 무위험 이자율', '시장 기대수익률 + 무위험 이자율', '베타 ÷ 무위험 이자율', 1, '시장 위험 프리미엄은 시장 전체의 기대수익률에서 무위험 이자율을 뺀 값이며, 여기에 베타를 곱한 뒤 무위험 이자율을 더해 CAPM 기대수익률을 구합니다.');
INSERT INTO quiz_questions VALUES (4, 9, '06', 'IPO', '공모가, 상장일 시초가, 상장일 종가에 대한 설명으로 가장 적절한 것은?', '세 가격은 항상 같다', '세 가격은 서로 다른 시점의 가격이며 공모가가 상장 후 가격을 보장하지 않는다', '상장일 종가만 의미가 있다', '공모가는 상장 후 절대 바뀌지 않는 회사의 정답 가치다', 1, '공모가는 청약 단계의 가격, 시초가는 상장일 장이 열릴 때 가격, 종가는 상장 첫날 마감 가격으로 서로 다르며, 공모가가 회사의 정답 가치이거나 상장 후 가격을 보장하지는 않습니다.');
INSERT INTO quiz_questions VALUES (4, 10, '06', '동전주', '동전주에 대한 설명으로 가장 적절한 것은?', '공식적으로 분류된 안전한 투자 등급이다', '주가가 매우 낮은 종목을 가볍게 부르는 시장 표현일 뿐이다', '가격이 낮으므로 항상 저평가된 것이다', '발행 주식 수와는 관계없이 회사 가치를 정확히 보여준다', 1, '동전주는 공식 분류가 아닌 시장 표현이며, 가격이 낮다는 사실만으로 회사가 싸거나 오를 가능성이 크다는 뜻은 아닙니다. 시가총액과 재무 상태를 함께 봐야 합니다.');
INSERT INTO quiz_questions VALUES (4, 11, '06', '주식대여', '주식대여(대주 서비스)에 대한 설명으로 가장 적절한 것은?', '보유 주식을 빌려주고 아무 조건 없이 이자만 받는 서비스다', '보유 주식을 빌려주고 수수료를 받되 배당·의결권·유동성 제약이 따를 수 있다', '개인 투자자는 이용할 수 없는 서비스다', '공매도와 전혀 관련이 없다', 1, '주식대여는 보유 주식을 빌려주고 수수료를 받는 서비스지만, 대여 기간 중 배당·의결권 행사가 제한되거나 중도 상환될 수 있습니다. 공매도에 필요한 주식 공급 경로 중 하나이기도 합니다.');
INSERT INTO quiz_questions VALUES (5, 5, '07', 'MDD', 'MDD(최대낙폭, Maximum Drawdown)에 대한 설명으로 가장 적절한 것은?', '관찰 기간 중 고점에서 저점까지의 가장 큰 하락률', '평균 수익률과 같은 개념', '미래의 최대 손실을 보장하는 수치', '항상 0%보다 큰 값', 0, 'MDD는 특정 관찰 기간 안에서 가장 나빴던 하락 폭을 보여줄 뿐이며, 관찰 기간을 다르게 잡으면 값이 달라지고 미래의 손실을 보장하지 않습니다.');
INSERT INTO quiz_questions VALUES (5, 6, '07', '과거 위기 비교', '과거 하락기와 현재 시장 상황을 비교할 때 가장 적절한 태도는?', '하락률 숫자만 비교해 위기의 크기를 단정한다', '하락의 원인이 무엇인지, 외환·신용시장에 실제 압박이 있는지 함께 확인한다', '과거보다 덜 빠졌으니 항상 안전하다고 판단한다', '원인과 관계없이 매번 같은 대응을 한다', 1, '1997년 외환위기, 2008년 금융위기, 2020년 코로나 충격은 각각 원인이 다르므로, 하락률만 비교하기보다 원인과 외환·신용시장 압박 여부를 함께 확인해야 합니다.');
